PROCEDURE @@proc@@ (p_name IN VARCHAR2) IS
    l_rows PLS_INTEGER;
BEGIN
    -- EXECUTE IMMEDIATE 'safe literal only';
    EXECUTE /* run it */ IMMEDIATE -- @expect
        'DELETE FROM @@tab@@ WHERE @@col@@ = ''' /* quoted */
        || p_name -- user supplied
        || '''';
    l_rows := SQL%ROWCOUNT;
    @@proc2@@(l_rows);
END @@proc@@;

PROCEDURE @@proc@@ (p_kind IN VARCHAR2, p_val IN VARCHAR2) IS
    l_stmt VARCHAR2(500);
BEGIN
    <<build>>
    BEGIN
        IF p_kind = 'LIKE' THEN
            l_stmt := 'DELETE FROM @@tab@@ WHERE @@col@@ LIKE ''%'
                      || p_val || '%''';
        ELSE
            l_stmt := 'DELETE FROM @@tab@@ WHERE 1 = 0';
        END IF;
    END build;
    DECLARE
        l_cnt NUMBER;
    BEGIN
        EXECUTE IMMEDIATE l_stmt; -- @expect
        l_cnt := SQL%ROWCOUNT;
        @@proc2@@(l_cnt);
    END;
END @@proc@@;

PROCEDURE @@proc@@ (p_tab IN VARCHAR2) IS
    PROCEDURE purge (p_name IN VARCHAR2) IS
    BEGIN
        EXECUTE IMMEDIATE 'TRUNCATE TABLE ' || p_name; -- @expect
    EXCEPTION
        WHEN OTHERS THEN
            RAISE;
    END purge;
BEGIN
    purge(p_tab);
    EXECUTE IMMEDIATE 'ANALYZE TABLE @@tab@@ COMPUTE STATISTICS';
END @@proc@@;

FUNCTION @@proc@@ (p_schema IN VARCHAR2, p_tab IN VARCHAR2, p_min IN NUMBER) RETURN NUMBER IS
    l_cnt NUMBER;
BEGIN
    EXECUTE IMMEDIATE -- @expect
        'SELECT COUNT(*) FROM '
        || DBMS_ASSERT.SCHEMA_NAME(p_schema)
        || '.'
        || p_tab
        || ' WHERE @@col@@ > :1'
        INTO l_cnt
        USING p_min;
    RETURN l_cnt;
END @@proc@@;

PROCEDURE @@proc@@ (p_order IN VARCHAR2, p_rc OUT SYS_REFCURSOR) IS
BEGIN
    IF p_order IS NULL THEN
        RAISE_APPLICATION_ERROR(-20011, 'order required');
    END IF;
    OPEN p_rc FOR -- @expect
        'SELECT "@@col@@", ''a;b'' AS sep FROM "@@tab@@" ORDER BY '
        || p_order;
END @@proc@@;

