PROCEDURE @@proc@@ (p_rc OUT SYS_REFCURSOR) IS
BEGIN
    -- OPEN p_rc FOR 'SELECT ' || p_rc;
    /* EXECUTE IMMEDIATE 'DROP TABLE x' || p_rc; */
    IF p_rc%ISOPEN THEN
        CLOSE p_rc;
    END IF;
    OPEN p_rc FOR
        'SELECT ''a || b'' AS joined, @@col@@ FROM @@tab@@';
END @@proc@@;

PROCEDURE @@proc@@ (p_name IN VARCHAR2) IS
    l_sql   VARCHAR2(500);
    l_label VARCHAR2(500);
BEGIN
    l_label := 'cleaning ' || p_name;
    DBMS_OUTPUT.PUT_LINE(l_label);
    l_sql := 'DELETE FROM '
             || DBMS_ASSERT.SQL_OBJECT_NAME(p_name)
             || ' WHERE @@col@@ IS NULL';
    EXECUTE IMMEDIATE l_sql;
END @@proc@@;

PROCEDURE @@proc@@ (p_val IN VARCHAR2, p_id IN NUMBER) IS
    l_out NUMBER;
BEGIN
    BEGIN
        EXECUTE IMMEDIATE 'INSERT INTO @@tab@@ (@@col@@, id) VALUES (:1, :2)'
            USING p_val || '_@@str@@', p_id;
    END;
    EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM @@tab@@ WHERE @@col@@ = :1'
        INTO l_out
        USING p_val || '_@@str@@';
    @@proc2@@(l_out);
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_sql VARCHAR2(500);

    FUNCTION build_sql (p_n IN NUMBER) RETURN VARCHAR2 IS
    BEGIN
        RETURN 'DELETE FROM @@tab@@ WHERE id = ' || TO_CHAR(p_n);
    END build_sql;
BEGIN
    l_sql := build_sql(p_id);
    EXECUTE IMMEDIATE l_sql;
END @@proc@@;

PROCEDURE @@proc@@ (p_dept IN NUMBER, p_rc OUT SYS_REFCURSOR) IS
BEGIN
    IF p_dept IS NULL THEN
        OPEN p_rc FOR
            SELECT @@col@@ FROM @@tab@@;
    ELSE
        OPEN p_rc FOR
            SELECT @@col@@ FROM @@tab@@ WHERE dept_id = p_dept;
    END IF;
    EXECUTE IMMEDIATE q'{ALTER SESSION SET NLS_DATE_FORMAT = 'YYYY-MM-DD'}'
                      || q'{ NLS_SORT = BINARY}';
END @@proc@@;
